package gateway
import("context";"encoding/json";"errors";"net/http/httptest";"strings";"testing";"github.com/madkoding/kitties/internal/kitty";"github.com/madkoding/kitties/internal/orchestrator")
type driveGatewayFleet struct{*fakeFleet;calls int;lastRead orchestrator.DriveRead;lastCommand orchestrator.DriveCommand;lastReconcile orchestrator.DriveReconcile;err error}
func(f *driveGatewayFleet)LexOpenDriveStatus(alias string)(orchestrator.DriveStatus,error){f.calls++;return orchestrator.DriveStatus{Alias:alias,Access:"manage",CanReadFiles:true,CanManageFiles:true,AccountRevision:strings.Repeat("a",64),Scopes:[]string{orchestrator.LexOpenDriveManageScope}},f.err}
func(f *driveGatewayFleet)LexOpenDriveRead(_ context.Context,_ string,b orchestrator.DriveRead)(orchestrator.DriveReadResult,error){f.calls++;f.lastRead=b;return orchestrator.DriveReadResult{Status:200,MIME:"application/pdf",BodyBase64:"eA==",Bytes:1,SHA256:strings.Repeat("b",64)},f.err}
func(f *driveGatewayFleet)LexOpenDriveCommand(_ context.Context,_ string,b orchestrator.DriveCommand)(orchestrator.DriveCommandResult,error){f.calls++;f.lastCommand=b;return orchestrator.DriveCommandResult{State:"drive_verified",RequestID:b.RequestID},f.err}
func(f *driveGatewayFleet)LexOpenDriveCommandStatus(_ string,id string)(orchestrator.DriveCommandResult,error){f.calls++;return orchestrator.DriveCommandResult{State:"unknown",RequestID:id},f.err}
func(f *driveGatewayFleet)LexOpenDriveReconcile(_ context.Context,_,id string,b orchestrator.DriveReconcile)(orchestrator.DriveCommandResult,error){f.calls++;f.lastReconcile=b;return orchestrator.DriveCommandResult{State:"unknown",RequestID:id},f.err}
func driveGatewayFixture()(*Server,*driveGatewayFleet){f:=&driveGatewayFleet{fakeFleet:&fakeFleet{kitties:map[string]*kitty.Kitty{}}};return New(f,&fakeChats{},"fixture-token","fixture"),f}
func TestLexOpenDriveManagementGatewayCapabilityAuthAndNoSecrets(t *testing.T){s,f:=driveGatewayFixture();rec:=httptest.NewRecorder();s.ServeHTTP(rec,httptest.NewRequest("GET","/v1/health",nil));var out map[string]any;json.Unmarshal(rec.Body.Bytes(),&out);if out["lexopen_drive_management"]!="v1"{t.Fatal("capability missing")};for _,tc:=range []struct{remote,token string;want int}{{"127.0.0.1:1234","fixture-token",200},{"[::1]:1234","fixture-token",200},{"192.0.2.5:1234","fixture-token",403},{"127.0.0.1:1234","wrong",401}}{req:=httptest.NewRequest("GET","/v1/lexopen/drive/altazor-google-0123456789abcdef/status",nil);req.RemoteAddr=tc.remote;req.Header.Set("Authorization","Bearer "+tc.token);rec:=httptest.NewRecorder();s.ServeHTTP(rec,req);if rec.Code!=tc.want||rec.Header().Get("Cache-Control")!="no-store"&&rec.Code==200{t.Fatal("status auth/boundary failed")}};f.err=errors.New("private-token-provider-detail");r:=lexopenOAuthRequest(s,"/v1/lexopen/drive/altazor-google-0123456789abcdef/read",map[string]any{"bindingRevision":strings.Repeat("a",64),"path":"/drive/v3/files","query":map[string]string{"pageSize":"5"},"max_bytes":1024},"127.0.0.1:1234","fixture-token");if r.Code!=503||strings.Contains(r.Body.String(),"private-token"){t.Fatal("unsafe error response")}}
func TestLexOpenDriveManagementGatewayExactWireAndRejectExtraFields(t *testing.T){s,f:=driveGatewayFixture();base:="/v1/lexopen/drive/altazor-google-0123456789abcdef";b:=map[string]any{"bindingRevision":strings.Repeat("a",64),"path":"/drive/v3/files","query":map[string]string{"pageSize":"50","fields":"files(id,name)"},"max_bytes":25*1024*1024};r:=lexopenOAuthRequest(s,base+"/read",b,"127.0.0.1:1234","fixture-token");if r.Code!=200||f.lastRead.MaxBytes!=25*1024*1024||f.lastRead.BindingRevision!=b["bindingRevision"]||f.lastRead.Query["pageSize"]!="50"{t.Fatal("read contract changed")};cmd:=map[string]any{"request_id":"exact-id","context_key":strings.Repeat("c",64),"bindingRevision":strings.Repeat("a",64),"action":"create_folder","folder_id":"root","name":"Cause","confirmed":true};r=lexopenOAuthRequest(s,base+"/commands",cmd,"127.0.0.1:1234","fixture-token");if r.Code!=200||f.lastCommand.RequestID!="exact-id"||f.lastCommand.FolderID!="root"{t.Fatal("command contract changed")};before:=f.calls;for _,raw:=range []string{`{"token":"forbidden"}`,`{} {}`,strings.Repeat("x",6*1024*1024+1)}{r=lexopenOAuthRequest(s,base+"/commands",raw,"127.0.0.1:1234","fixture-token");if r.Code!=400||f.calls!=before{t.Fatal("bad body reached implementation")}};r=lexopenOAuthRequest(s,base+"/commands/exact-id/reconcile",map[string]any{"context_key":strings.Repeat("c",64),"bindingRevision":strings.Repeat("a",64),"confirmed":true},"127.0.0.1:1234","fixture-token");if r.Code!=200||!f.lastReconcile.Confirmed{t.Fatal("reconcile contract changed")}}
func TestLexOpenDriveManagementFullScopeImportAndDowngrade(t *testing.T){s,fleet:=lexopenOAuthServer(t);name:="altazor-google-0123456789abcdef";b:=lexopenOAuthBody();b["scopes"]=[]string{"https://www.googleapis.com/auth/drive"};b["account"]="fixture-account";r:=lexopenOAuthRequest(s,"/v1/lexopen/easy-oauth/"+name,b,"127.0.0.1:1234","fixture-gateway-token");if r.Code!=200{t.Fatal("exact full scope import rejected")};a,e:=fleet.LexOpenDriveStatus(name);if e!=nil||!a.CanManageFiles||!a.CanReadFiles{t.Fatal("full grant not opt-in management")};app,_:=fleet.OAuthApp(name);if app.Settings["oauth_lexopen_drive_management"]!="v1"||app.Settings["oauth_lexopen_import_revision"]==""{t.Fatal("native grant marker/generation missing")};readBody:=lexopenOAuthBody();readBody["account"]="fixture-account";r=lexopenOAuthRequest(s,"/v1/lexopen/easy-oauth/"+name,readBody,"127.0.0.1:1234","fixture-gateway-token");if r.Code!=200{t.Fatal("read downgrade rejected")};a2,e:=fleet.LexOpenDriveStatus(name);if e!=nil||a2.CanManageFiles||!a2.CanReadFiles||a2.AccountRevision==a.AccountRevision{t.Fatal("downgrade retained write capability or generation")};b["scopes"]=[]string{"https://www.googleapis.com/auth/drive","https://www.googleapis.com/auth/gmail.modify"};if r=lexopenOAuthRequest(s,"/v1/lexopen/easy-oauth/"+name,b,"127.0.0.1:1234","fixture-gateway-token");r.Code!=400{t.Fatal("unrelated Google scopes accepted")}}
